WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions WHERE name = 'base_ftp_aero_4w_w4s3_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Blocs au seuil en position libre, récupération facile entre chaque. On termine par un bloc à 70 % FTP en position aéro : c''est là que tu apprends à rester bas quand les jambes sont lourdes.", "en": "Threshold blocks in any position, easy recovery between them. We finish with a block at 70% FTP in the aero position: that''s where you learn to stay low on tired legs.", "es": "Bloques de umbral en posición libre, recuperación suave entre ellos. Terminamos con un bloque al 70 % FTP en posición aero: ahí aprendes a seguir abajo con las piernas cansadas.", "it": "Blocchi alla soglia in posizione libera, recupero facile tra un blocco e l''altro. Si chiude con un blocco al 70 % FTP in posizione aero: è lì che impari a restare basso con le gambe stanche.", "de": "Schwellenblöcke in freier Position, lockere Erholung dazwischen. Zum Schluss ein Block bei 70 % FTP in Aeroposition: Hier lernst du, mit müden Beinen tief zu bleiben.", "nl": "Drempelblokken in vrije houding, rustig herstel ertussen. We sluiten af met een blok op 70 % FTP in aerohouding: daar leer je laag te blijven met vermoeide benen.", "pt": "Blocos no limiar em posição livre, recuperação leve entre eles. Terminamos com um bloco a 70 % FTP na posição aero: é aí que você aprende a ficar baixo com as pernas cansadas.", "ja": "ポジション自由で閾値ブロック、間は楽に回復。最後に70 % FTPでエアロポジションのブロック。脚が重い時こそ低い姿勢を保つ練習です。", "tr": "Serbest pozisyonda eşik blokları, aralarında kolay toparlanma. Aero pozisyonda %70 FTP''lik bir blokla bitiriyoruz: yorgun bacaklarla alçakta kalmayı burada öğrenirsin."}'::jsonb,
  'objectif', replace('{"fr": "Faire monter ta FTP, puis tenir la position aéro à 70 % sous fatigue", "en": "Raise your FTP, then hold the aero position at 70% under fatigue", "es": "Subir tu FTP y luego mantener la posición aero al 70 % con fatiga", "it": "Alzare la tua FTP, poi tenere la posizione aero al 70 % sotto fatica", "de": "Deine FTP steigern und danach die Aeroposition bei 70 % unter Ermüdung halten", "nl": "Je FTP verhogen en daarna de aerohouding op 70 % vasthouden onder vermoeidheid", "pt": "Aumentar sua FTP e depois manter a posição aero a 70 % sob fadiga", "ja": "FTPを高め、疲労下で70 %のエアロポジションを維持する", "tr": "FTP''ni yükselt, ardından yorgunken %70''te aero pozisyonu koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s1_name', 'base_ftp_aero_4w_w2s1_name', 'base_ftp_aero_4w_w3s1_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "La séance clé du plan : des blocs à 70 % FTP en position aéro, de plus en plus longs d''une semaine à l''autre. L''intensité reste facile pour que toute ton attention aille à la position : tête basse, épaules relâchées, respiration calme. Entre les blocs, redresse-toi.", "en": "The key session of the plan: blocks at 70% FTP in the aero position, longer every week. The intensity stays easy so all your attention goes to the position: head low, shoulders relaxed, calm breathing. Sit up between blocks.", "es": "La sesión clave del plan: bloques al 70 % FTP en posición aero, más largos cada semana. La intensidad es suave para que toda tu atención vaya a la posición: cabeza baja, hombros relajados, respiración tranquila. Entre bloques, incorpórate.", "it": "La sessione chiave del piano: blocchi al 70 % FTP in posizione aero, sempre più lunghi di settimana in settimana. L''intensità resta facile perché tutta l''attenzione vada alla posizione: testa bassa, spalle rilassate, respiro calmo. Tra i blocchi, rialzati.", "de": "Die Schlüsseleinheit des Plans: Blöcke bei 70 % FTP in Aeroposition, jede Woche länger. Die Intensität bleibt leicht, damit deine ganze Aufmerksamkeit der Position gilt: Kopf tief, Schultern locker, ruhige Atmung. Zwischen den Blöcken aufrichten.", "nl": "De kernsessie van het plan: blokken op 70 % FTP in aerohouding, elke week langer. De intensiteit blijft licht zodat al je aandacht naar de houding gaat: hoofd laag, schouders ontspannen, rustige ademhaling. Kom tussen de blokken overeind.", "pt": "A sessão-chave do plano: blocos a 70 % FTP na posição aero, mais longos a cada semana. A intensidade é leve para que toda a sua atenção vá para a posição: cabeça baixa, ombros relaxados, respiração calma. Entre os blocos, levante o tronco.", "ja": "プランの核となるセッション：70 % FTPのエアロポジションのブロックを週ごとに長くします。強度は楽なので、ポジションに集中：頭を低く、肩の力を抜き、呼吸を落ち着けて。ブロックの間は上体を起こします。", "tr": "Planın anahtar seansı: aero pozisyonda %70 FTP''de, her hafta uzayan bloklar. Yoğunluk kolay kalır ki tüm dikkatin pozisyonda olsun: baş aşağıda, omuzlar gevşek, sakin nefes. Bloklar arasında doğrul."}'::jsonb,
  'objectif', replace('{"fr": "Tenir la position aéro {aero} minutes à 70 % FTP", "en": "Hold the aero position for {aero} minutes at 70% FTP", "es": "Mantener la posición aero {aero} minutos al 70 % FTP", "it": "Tenere la posizione aero {aero} minuti al 70 % FTP", "de": "Die Aeroposition {aero} Minuten bei 70 % FTP halten", "nl": "De aerohouding {aero} minuten vasthouden op 70 % FTP", "pt": "Manter a posição aero {aero} minutos a 70 % FTP", "ja": "70 % FTPでエアロポジションを{aero}分維持", "tr": "%70 FTP''de aero pozisyonu {aero} dakika koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s2_name', 'base_ftp_aero_4w_w2s2_name', 'base_ftp_aero_4w_w3s2_name', 'base_ftp_aero_4w_w4s2_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Efforts courts au-dessus du seuil, position libre, récupération égale à l''effort. Un bloc à 70 % en aéro clôt la séance.", "en": "Short efforts above threshold, any position, recovery as long as the effort. A block at 70% in the aero position closes the session.", "es": "Esfuerzos cortos por encima del umbral, posición libre, recuperación igual al esfuerzo. Un bloque al 70 % en aero cierra la sesión.", "it": "Sforzi brevi sopra la soglia, posizione libera, recupero pari allo sforzo. Un blocco al 70 % in aero chiude la sessione.", "de": "Kurze Belastungen über der Schwelle, freie Position, Erholung so lang wie die Belastung. Ein Block bei 70 % in Aeroposition schließt die Einheit ab.", "nl": "Korte inspanningen boven de drempel, vrije houding, herstel even lang als de inspanning. Een blok op 70 % in aero sluit de sessie af.", "pt": "Esforços curtos acima do limiar, posição livre, recuperação igual ao esforço. Um bloco a 70 % em aero encerra a sessão.", "ja": "閾値を超える短い努力、ポジション自由、回復は努力と同じ長さ。最後は70 %のエアロブロックで締めます。", "tr": "Eşiğin üzerinde kısa eforlar, serbest pozisyon, eforla eşit toparlanma. Seansı %70''te bir aero blok kapatır."}'::jsonb,
  'objectif', replace('{"fr": "Faire monter ta puissance critique et ta PMA", "en": "Raise your critical power and VO2max", "es": "Subir tu potencia crítica y tu VO2max", "it": "Alzare la tua potenza critica e il VO2max", "de": "Deine kritische Leistung und VO2max steigern", "nl": "Je kritisch vermogen en VO2max verhogen", "pt": "Aumentar sua potência crítica e seu VO2max", "ja": "クリティカルパワーとVO2maxを高める", "tr": "Kritik gücünü ve VO2max''ını yükselt"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w1s3_name', 'base_ftp_aero_4w_w2s3_name', 'base_ftp_aero_4w_w3s3_name', 'base_ftp_aero_4w_w4s3_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Sortie longue en endurance, le cœur du travail aérobie. Le bloc central est en aéro à 70 % FTP, sans interruption : cherche une position que tu peux tenir, pas la plus basse.", "en": "Long endurance ride, the core of aerobic work. The central block is aero at 70% FTP with no break: find a position you can hold, not the lowest one.", "es": "Salida larga de resistencia, el corazón del trabajo aeróbico. El bloque central es en aero al 70 % FTP sin pausa: busca una posición que puedas mantener, no la más baja.", "it": "Uscita lunga di resistenza, il cuore del lavoro aerobico. Il blocco centrale è in aero al 70 % FTP senza interruzioni: cerca una posizione che puoi tenere, non la più bassa.", "de": "Lange Ausdauerfahrt, der Kern der aeroben Arbeit. Der Mittelblock ist Aero bei 70 % FTP ohne Unterbrechung: Such eine Position, die du halten kannst, nicht die tiefste.", "nl": "Lange duurrit, de kern van het aerobe werk. Het middenblok is aero op 70 % FTP zonder onderbreking: zoek een houding die je kunt volhouden, niet de laagste.", "pt": "Treino longo de resistência, o coração do trabalho aeróbio. O bloco central é em aero a 70 % FTP sem pausa: procure uma posição que consiga manter, não a mais baixa.", "ja": "有酸素トレーニングの中心となるロングライド。中央ブロックは70 % FTPのエアロを途切れず：一番低い姿勢ではなく、維持できる姿勢を探して。", "tr": "Aerobik çalışmanın kalbi olan uzun dayanıklılık sürüşü. Orta blok ara vermeden %70 FTP''de aero: en alçak değil, koruyabileceğin bir pozisyon bul."}'::jsonb,
  'objectif', replace('{"fr": "Construire la base aérobie avec {aero} minutes d''aéro d''affilée", "en": "Build your aerobic base with {aero} minutes of aero in one go", "es": "Construir la base aeróbica con {aero} minutos seguidos en aero", "it": "Costruire la base aerobica con {aero} minuti di aero di fila", "de": "Die aerobe Basis aufbauen, mit {aero} Minuten Aero am Stück", "nl": "Je aerobe basis opbouwen met {aero} minuten aero aan één stuk", "pt": "Construir a base aeróbia com {aero} minutos seguidos em aero", "ja": "{aero}分連続のエアロで有酸素ベースを作る", "tr": "Aralıksız {aero} dakika aero ile aerobik temel oluştur"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w2s4_name', 'base_ftp_aero_4w_w3s4_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object(
  'info', '{"fr": "Semaine plus légère : le corps assimile les trois semaines de travail. Deux blocs sweet spot, puis 10 minutes en aéro à 70 %.", "en": "Lighter week: your body absorbs three weeks of work. Two sweet spot blocks, then 10 minutes aero at 70%.", "es": "Semana más ligera: el cuerpo asimila tres semanas de trabajo. Dos bloques sweet spot y luego 10 minutos en aero al 70 %.", "it": "Settimana più leggera: il corpo assimila tre settimane di lavoro. Due blocchi sweet spot, poi 10 minuti in aero al 70 %.", "de": "Leichtere Woche: Der Körper verarbeitet drei Trainingswochen. Zwei Sweet-Spot-Blöcke, dann 10 Minuten Aero bei 70 %.", "nl": "Lichtere week: je lichaam verwerkt drie weken training. Twee sweetspotblokken, daarna 10 minuten aero op 70 %.", "pt": "Semana mais leve: o corpo assimila três semanas de trabalho. Dois blocos sweet spot e depois 10 minutos em aero a 70 %.", "ja": "軽めの週：3週間の負荷を体に吸収させます。スイートスポット2本の後、70 %でエアロ10分。", "tr": "Daha hafif hafta: vücut üç haftalık çalışmayı özümser. İki sweet spot bloğu, ardından %70''te 10 dakika aero."}'::jsonb,
  'objectif', replace('{"fr": "Entretenir la FTP en semaine d''assimilation", "en": "Maintain your FTP during the recovery week", "es": "Mantener la FTP en la semana de asimilación", "it": "Mantenere la FTP nella settimana di scarico", "de": "Die FTP in der Entlastungswoche erhalten", "nl": "Je FTP onderhouden in de herstelweek", "pt": "Manter a FTP na semana de assimilação", "ja": "回復週にFTPを維持する", "tr": "Toparlanma haftasında FTP''ni koru"}', '{aero}', (aero_duration_sec / 60)::text)::jsonb)
WHERE name IN ('base_ftp_aero_4w_w4s1_name');

UPDATE public.training_sessions
SET translations_json = translations_json || jsonb_build_object('live_comments', '{"base_ftp_aero_4w_lc_start": {"fr": "Bloc aéro à 70 % : passe sur les prolongateurs, relâche les épaules et tiens jusqu''au bout du bloc.", "en": "Aero block at 70%: get on the extensions, relax your shoulders and hold until the end of the block.", "es": "Bloque aero al 70 %: ponte en los acoples, relaja los hombros y aguanta hasta el final del bloque.", "it": "Blocco aero al 70 %: mettiti sulle protesi, rilassa le spalle e tieni fino alla fine del blocco.", "de": "Aero-Block bei 70 %: Ab auf den Aufsatz, Schultern locker und bis zum Ende des Blocks halten.", "nl": "Aeroblok op 70 %: ga op de opzetstukken, ontspan je schouders en houd vol tot het einde van het blok.", "pt": "Bloco aero a 70 %: vá para o clipe, relaxe os ombros e aguente até o fim do bloco.", "ja": "70 %のエアロブロック：エアロバーに乗り、肩の力を抜いてブロックの最後まで維持しよう。", "tr": "%70''te aero blok: uzatmalara geç, omuzlarını gevşet ve blok bitene kadar koru."}, "base_ftp_aero_4w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}}'::jsonb)
WHERE name LIKE 'base_ftp_aero_4w\_w%' ESCAPE '\';

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'base_ftp_aero_4w_name', 'base_ftp_aero_4w_description', 'base_ftp_aero_4w_objective', 4, 'intermediate', 'training', 4, true, '{"name": {"fr": "Base aérobie, FTP & aéro", "en": "Aerobic base, FTP & aero", "es": "Base aeróbica, FTP y aero", "it": "Base aerobica, FTP e aero", "de": "Aerobe Basis, FTP & Aero", "nl": "Aerobe basis, FTP & aero", "pt": "Base aeróbia, FTP e aero", "ja": "有酸素ベース・FTP・エアロ", "tr": "Aerobik temel, FTP ve aero"}, "objective": {"fr": "Construire ta base aérobie, faire monter ta FTP et ta puissance critique, et tenir la position aéro 45 minutes d''affilée à 70 % FTP.", "en": "Build your aerobic base, raise your FTP and critical power, and hold the aero position for 45 minutes in a row at 70% FTP.", "es": "Construir tu base aeróbica, subir tu FTP y tu potencia crítica, y mantener la posición aero 45 minutos seguidos al 70 % FTP.", "it": "Costruire la base aerobica, alzare FTP e potenza critica, e tenere la posizione aero 45 minuti di fila al 70 % FTP.", "de": "Deine aerobe Basis aufbauen, FTP und kritische Leistung steigern und die Aeroposition 45 Minuten am Stück bei 70 % FTP halten.", "nl": "Je aerobe basis opbouwen, je FTP en kritisch vermogen verhogen en de aerohouding 45 minuten aan één stuk vasthouden op 70 % FTP.", "pt": "Construir sua base aeróbia, aumentar sua FTP e potência crítica e manter a posição aero 45 minutos seguidos a 70 % FTP.", "ja": "有酸素ベースを作り、FTPとクリティカルパワーを高め、70 % FTPでエアロポジションを45分連続で維持する。", "tr": "Aerobik temelini oluştur, FTP''ni ve kritik gücünü yükselt, aero pozisyonu %70 FTP''de aralıksız 45 dakika koru."}, "description": {"fr": "4 semaines, 3 à 4 séances de 45 à 80 minutes. Chaque semaine : une séance au seuil, une séance de PMA, une séance d''endurance aéro et, en semaines 2 et 3, une sortie longue. Les blocs aéro à 70 % FTP s''allongent de 10 à 45 minutes. La semaine 4 est allégée pour assimiler : refais un test FTP juste après.", "en": "4 weeks, 3 to 4 sessions of 45 to 80 minutes. Each week: one threshold session, one VO2max session, one aero endurance session and, in weeks 2 and 3, a long ride. Aero blocks at 70% FTP grow from 10 to 45 minutes. Week 4 is lighter to absorb the work: do an FTP test right after.", "es": "4 semanas, 3 a 4 sesiones de 45 a 80 minutos. Cada semana: una sesión de umbral, una de VO2max, una de resistencia aero y, en las semanas 2 y 3, una salida larga. Los bloques aero al 70 % FTP pasan de 10 a 45 minutos. La semana 4 es más ligera para asimilar: haz un test FTP justo después.", "it": "4 settimane, da 3 a 4 sessioni da 45 a 80 minuti. Ogni settimana: una sessione alla soglia, una di VO2max, una di resistenza aero e, nelle settimane 2 e 3, un''uscita lunga. I blocchi aero al 70 % FTP passano da 10 a 45 minuti. La settimana 4 è più leggera per assimilare: rifai un test FTP subito dopo.", "de": "4 Wochen, 3 bis 4 Einheiten von 45 bis 80 Minuten. Jede Woche: eine Schwelleneinheit, eine VO2max-Einheit, eine Aero-Ausdauereinheit und in Woche 2 und 3 eine lange Fahrt. Die Aero-Blöcke bei 70 % FTP wachsen von 10 auf 45 Minuten. Woche 4 ist leichter zur Erholung: Mach direkt danach einen FTP-Test.", "nl": "4 weken, 3 tot 4 sessies van 45 tot 80 minuten. Elke week: een drempelsessie, een VO2max-sessie, een aero-duursessie en in week 2 en 3 een lange rit. De aeroblokken op 70 % FTP groeien van 10 naar 45 minuten. Week 4 is lichter om te herstellen: doe direct daarna een FTP-test.", "pt": "4 semanas, 3 a 4 sessões de 45 a 80 minutos. Toda semana: uma sessão de limiar, uma de VO2max, uma de resistência aero e, nas semanas 2 e 3, um treino longo. Os blocos aero a 70 % FTP passam de 10 para 45 minutos. A semana 4 é mais leve para assimilar: faça um teste FTP logo depois.", "ja": "4週間、45〜80分のセッションを週3〜4回。毎週：閾値1回、VO2max 1回、エアロ持久1回、2・3週目はロングライド。70 % FTPのエアロブロックは10分から45分へ。4週目は軽めで吸収、直後にFTPテストを。", "tr": "4 hafta, haftada 45-80 dakikalık 3-4 seans. Her hafta: bir eşik seansı, bir VO2max seansı, bir aero dayanıklılık seansı ve 2. ile 3. haftalarda uzun sürüş. %70 FTP''deki aero bloklar 10''dan 45 dakikaya uzar. 4. hafta özümseme için daha hafif: hemen ardından bir FTP testi yap."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'base_ftp_aero_4w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'base_ftp_aero_4w_w1s1_name'), (1, 2, 'base_ftp_aero_4w_w1s2_name'), (1, 3, 'base_ftp_aero_4w_w1s3_name'), (2, 1, 'base_ftp_aero_4w_w2s1_name'), (2, 2, 'base_ftp_aero_4w_w2s2_name'), (2, 3, 'base_ftp_aero_4w_w2s3_name'), (2, 4, 'base_ftp_aero_4w_w2s4_name'), (3, 1, 'base_ftp_aero_4w_w3s1_name'), (3, 2, 'base_ftp_aero_4w_w3s2_name'), (3, 3, 'base_ftp_aero_4w_w3s3_name'), (3, 4, 'base_ftp_aero_4w_w3s4_name'), (4, 1, 'base_ftp_aero_4w_w4s1_name'), (4, 2, 'base_ftp_aero_4w_w4s2_name'), (4, 3, 'base_ftp_aero_4w_w4s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'base_ftp_aero_4w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);

